#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>
#include <openssl/evp.h>

/* OpenSSL low-level ChaCha20 and Poly1305 */
extern void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp,
                           size_t len, const unsigned int key[8],
                           const unsigned int counter[4]);

typedef struct poly1305_context POLY1305;
extern size_t Poly1305_ctx_size(void);
extern void Poly1305_Init(POLY1305 *ctx, const unsigned char key[32]);
extern void Poly1305_Update(POLY1305 *ctx, const unsigned char *inp, size_t len);
extern void Poly1305_Final(POLY1305 *ctx, unsigned char mac[16]);

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

#define NTHREADS 6

typedef struct {
    const unsigned char *in;
    unsigned char *out;
    size_t len;
    unsigned int key[8];
    unsigned int counter[4];
    uint64_t block_start; /* starting 64-byte block index */
} job_t;

static void *worker(void *arg) {
    job_t *j = arg;
    unsigned int ctr[4];
    ctr[0] = j->counter[0];
    ctr[1] = j->counter[1];
    ctr[2] = (unsigned int)(j->block_start & 0xffffffffu);
    ctr[3] = (unsigned int)(j->block_start >> 32);
    /* add base counter (usually 1) */
    unsigned long long base = ((unsigned long long)j->counter[3] << 32) | j->counter[2];
    unsigned long long c = base + j->block_start;
    ctr[2] = (unsigned int)(c & 0xffffffffu);
    ctr[3] = (unsigned int)(c >> 32);
    ChaCha20_ctr32(j->out, j->in, j->len, j->key, ctr);
    return NULL;
}

int main() {
    size_t len = 40960000;
    unsigned char *in = malloc(len);
    unsigned char *out = malloc(len+64);
    memset(in, 0x5a, len);
    unsigned int key[8];
    for (int i=0;i<8;i++) key[i]=0x01020304+i;
    unsigned int counter[4] = {0,0,1,0}; /* chacha20-poly1305 starts counter at 1 */

    /* single thread */
    double t0 = now();
    int iters = 5;
    for (int i=0;i<iters;i++) {
        ChaCha20_ctr32(out, in, len, key, counter);
    }
    double t1 = now();
    printf("single thread ChaCha20: %.2f ms  %.1f MB/s\n", (t1-t0)/iters*1000, (len/1e6)/((t1-t0)/iters));

    /* multi thread */
    pthread_t th[NTHREADS];
    job_t jobs[NTHREADS];
    size_t chunk = (len / NTHREADS) & ~((size_t)63);
    t0 = now();
    for (int it=0; it<iters; it++) {
        size_t off = 0;
        for (int i=0;i<NTHREADS;i++) {
            size_t L = (i==NTHREADS-1) ? (len-off) : chunk;
            jobs[i].in = in+off;
            jobs[i].out = out+off;
            jobs[i].len = L;
            memcpy(jobs[i].key, key, sizeof key);
            memcpy(jobs[i].counter, counter, sizeof counter);
            jobs[i].block_start = off/64;
            off += L;
            pthread_create(&th[i], NULL, worker, &jobs[i]);
        }
        for (int i=0;i<NTHREADS;i++) pthread_join(th[i], NULL);
    }
    t1 = now();
    printf("%d thread ChaCha20: %.2f ms  %.1f MB/s\n", NTHREADS, (t1-t0)/iters*1000, (len/1e6)/((t1-t0)/iters));

    /* poly1305 single */
    size_t ctxsz = Poly1305_ctx_size();
    void *ctx = malloc(ctxsz+64);
    unsigned char pkey[32] = {0};
    unsigned char mac[16];
    t0 = now();
    for (int i=0;i<iters;i++) {
        Poly1305_Init(ctx, pkey);
        Poly1305_Update(ctx, out, len);
        Poly1305_Final(ctx, mac);
    }
    t1 = now();
    printf("Poly1305: %.2f ms  %.1f MB/s\n", (t1-t0)/iters*1000, (len/1e6)/((t1-t0)/iters));

    /* EVP chacha20-poly1305 */
    EVP_CIPHER_CTX *cctx = EVP_CIPHER_CTX_new();
    EVP_CIPHER *cipher = EVP_CIPHER_fetch(NULL, "ChaCha20-Poly1305", NULL);
    unsigned char keyb[32]={0}, iv[12]={0}, tag[16];
    unsigned char *ct = malloc(len+16);
    t0 = now();
    for (int i=0;i<iters;i++) {
        EVP_EncryptInit_ex(cctx, cipher, NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(cctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(cctx, NULL, NULL, keyb, iv);
        int outl=0, tmplen=0;
        EVP_EncryptUpdate(cctx, ct, &outl, in, (int)len);
        EVP_EncryptFinal_ex(cctx, ct+outl, &tmplen);
        EVP_CIPHER_CTX_ctrl(cctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
    }
    t1 = now();
    printf("EVP ChaCha20-Poly1305: %.2f ms  %.1f MB/s\n", (t1-t0)/iters*1000, (len/1e6)/((t1-t0)/iters));
    return 0;
}
EOF
