extern void Poly1305_Final(POLY1305 *ctx, unsigned char mac[16]);

static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}

#define NT 4
typedef struct { const unsigned char *in; size_t len; unsigned char key[32]; unsigned char mac[16]; size_t ctxsz; } job;
static void *w(void *a){ job*j=a; void*ctx=malloc(j->ctxsz+64);
    Poly1305_Init(ctx, j->key); Poly1305_Update(ctx, j->in, j->len); Poly1305_Final(ctx, j->mac); free(ctx); return NULL; }

int main(){
    size_t len=40960000;
