    for(int i=0;i<iters;i++){ Poly1305_Init(ctx,key); Poly1305_Update(ctx,in,len); Poly1305_Final(ctx,mac); }
    double t1=now();
    printf("poly single: %.2f ms %.1f MB/s\n",(t1-t0)/iters*1000,(len/1e6)/((t1-t0)/iters));

    /* parallel independent chunks */
    pthread_t th[NT]; job jobs[NT];
    size_t chunk=len/NT;
    t0=now();
    for(int it=0;it<iters;it++){
        size_t off=0;
        for(int i=0;i<NT;i++){
            jobs[i].in=in+off; jobs[i].len=(i==NT-1)?len-off:chunk; memcpy(jobs[i].key,key,32); jobs[i].ctxsz=ctxsz; off+=jobs[i].len;
            pthread_create(&th[i],NULL,w,&jobs[i]);
        }
        for(int i=0;i<NT;i++) pthread_join(th[i],NULL);
    }
    t1=now();
    printf("poly %d-thread chunks: %.2f ms %.1f MB/s\n",NT,(t1-t0)/iters*1000,(len/1e6)/((t1-t0)/iters));

    /* aligned 16 chunk */
    return 0;
}
