#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

typedef struct poly1305_context POLY1305;
extern size_t Poly1305_ctx_size(void);
extern void Poly1305_Init(POLY1305 *ctx, const unsigned char key[32]);
extern void Poly1305_Update(POLY1305 *ctx, const unsigned char *inp, size_t len);
extern void Poly1305_Final(POLY1305 *ctx, unsigned char mac[16]);

static void dump(const char *label, unsigned char *ctx, size_t n){
    printf("%s:\n", label);
    for(size_t i=0;i<n;i++){
        printf("%02x%s", ctx[i], ((i+1)%16==0)?"\n":" ");
    }
    printf("\n");
}

int main(){
    size_t sz = Poly1305_ctx_size();
    printf("ctx size = %zu\n", sz);
    unsigned char *ctx = aligned_alloc(64, (sz+63)&~63);
    unsigned char key[32];
    for(int i=0;i<32;i++) key[i]=i+1;
    memset(ctx, 0xAA, sz);
    Poly1305_Init(ctx, key);
    dump("after init", ctx, sz);

    /* feed 16 bytes */
    unsigned char block[64];
    for(int i=0;i<64;i++) block[i]=0x10+i;
    Poly1305_Update(ctx, block, 16);
    dump("after 16 bytes", ctx, sz);

    /* reset and feed 32 */
    memset(ctx,0xAA,sz);
    Poly1305_Init(ctx,key);
    Poly1305_Update(ctx, block, 32);
    dump("after 32 bytes", ctx, sz);

    /* reset and feed 15 (partial) */
    memset(ctx,0xAA,sz);
    Poly1305_Init(ctx,key);
    Poly1305_Update(ctx, block, 15);
    dump("after 15 bytes", ctx, sz);

    /* feed exactly 16 then final to see s usage */
    memset(ctx,0xAA,sz);
    Poly1305_Init(ctx,key);
    Poly1305_Update(ctx, block, 16);
    unsigned char mac[16];
    /* copy ctx before final */
    unsigned char *ctx2 = malloc(sz);
    memcpy(ctx2, ctx, sz);
    Poly1305_Final(ctx, mac);
    printf("mac: "); for(int i=0;i<16;i++) printf("%02x", mac[i]); printf("\n");
    dump("after final", ctx, sz);

    /* empty message mac */
    memset(ctx,0xAA,sz);
    Poly1305_Init(ctx,key);
    Poly1305_Final(ctx, mac);
    printf("empty mac: "); for(int i=0;i<16;i++) printf("%02x", mac[i]); printf("\n");
    return 0;
}
EOF
