{"command":"cat > "$TMPDIR/chacha/ceil.c" << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>
#include <stdatomic.h>

extern void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp,
                           size_t len, const unsigned int key[8],
                           const unsigned int counter[4]);

static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}

#define MAXTHREADS 12
typedef struct {
    const unsigned char *in; unsigned char *out; size_t len;
    unsigned int key[8]; unsigned int counter[4]; uint64_t block_start;
    atomic_int *go; atomic_int *done; int id; int nthreads;
} worker_t;

static void *worker(void *arg){
    worker_t *w = arg;
    int epoch = 0;
    for(;;){
        epoch++;
        while(atomic_load(w->go) < epoch) { /* spin */ }
        if(atomic_load(w->go) < 0) break;
        unsigned int ctr[4];
        unsigned long long base = ((unsigned long long)w->counter[3]<<32)|w->counter[2];
        unsigned long long c = base + w->block_start;
        ctr[0]=w->counter[0]; ctr[1]=w->counter[1];
        ctr[2]=(unsigned int)(c & 0xffffffffu); ctr[3]=(unsigned int)(c>>32);
        ChaCha20_ctr32(w->out, w->in, w->len, w->key, ctr);
        atomic_fetch_add(w->done, 1);
    }
    return NULL;
}

static void run_chacha(int nt, size_t len, int iters){
    unsigned char *in = aligned_alloc(64, len);
    unsigned char *out = aligned_alloc(64, len);
    memset(in, 0x5a, len);
    unsigned int key[8]; for(int i=0;i<8;i++) key[i]=0x11111111*i+1;
    unsigned int counter[4]={0,0,1,0};

    atomic_int go=0, done=0;
    pthread_t th[MAXTHREADS];
    worker_t ws[MAXTHREADS];
    size_t chunk = (len/nt) & ~((size_t)63);
    size_t off=0;
    for(int i=0;i<nt;i++){
        size_t L = (i==nt-1)? (len-off): chunk;
        ws[i].in=in+off; ws[i].out=out+off; ws[i].len=L;
        memcpy(ws[i].key,key,32); memcpy(ws[i].counter,counter,16);
        ws[i].block_start=off/64; ws[i].go=&go; ws[i].done=&done; ws[i].id=i; ws[i].nthreads=nt;
        off+=L;
        pthread_create(&th[i],NULL,worker,&ws[i]);
    }
    /* warmup */
    for(int k=0;k<2;k++){ atomic_store(&done,0); atomic_fetch_add(&go,1); while(atomic_load(&done)<nt); }
    double t0=now();
    for(int k=0;k<iters;k++){ atomic_store(&done,0); atomic_fetch_add(&go,1); while(atomic_load(&done)<nt); }
    double t1=now();
    printf("chacha persistent %2d thr: %.3f ms  %.1f MB/s\n", nt, (t1-t0)/iters*1000, (len/1e6)/((t1-t0)/iters));
    atomic_store(&go,-1);
    for(int i=0;i<nt;i++) pthread_join(th[i],NULL);
    free(in); free(out);
}

static void bandwidth(int nt, size_t len, int iters){
    unsigned char *a=aligned_alloc(64,len), *b=aligned_alloc(64,len), *c=aligned_alloc(64,len);
    memset(a,1,len); memset(b,2,len);
    double t0=now();
    for(int i=0;i<iters;i++){
        /* triad: c = a + b  (read 2, write 1) */
        size_t n=len/8; uint64_t *A=(uint64_t*)a,*B=(uint64_t*)b,*C=(uint64_t*)c;
        for(size_t j=0;j<n;j++) C[j]=A[j]+B[j];
    }
    double t1=now();
    double bytes = 3.0*len;
    printf("triad single: %.3f ms  %.1f MB/s aggregate\n",(t1-t0)/iters*1000,(bytes/1e6)/((t1-t0)/iters));
    free(a);free(b);free(c);
}

int main(){
    size_t len=40960000;
    bandwidth(1,len,5);
    for(int nt=1; nt<=12; nt++) run_chacha(nt, len, 8);
    return 0;
}
EOF
