extern void Poly1305_Final(POLY1305*, unsigned char mac[16]);

static void chacha20_block(unsigned char out[64], const unsigned int key[8], const unsigned int counter[4]){
    unsigned char zero[64]={0};
    ChaCha20_ctr32(out, zero, 64, key, counter);
}

/* RFC 8439 AEAD encrypt, single threaded, for correctness reference */
static void aead_ref(unsigned char *ct, unsigned char tag[16],
                     const unsigned char key[32], const unsigned char nonce[12],
                     const unsigned char *pt, size_t ptlen,
                     const unsigned char *aad, size_t aadlen){
    unsigned int k[8]; memcpy(k, key, 32);
    unsigned int ctr0[4]={0,0,0,0};
    memcpy(&ctr0[1], nonce, 12); /* little endian layout: counter word then nonce */
    unsigned char block0[64];
    chacha20_block(block0, k, ctr0);
    unsigned char otk[32]; memcpy(otk, block0, 32);

    unsigned int ctr1[4]; memcpy(ctr1, ctr0, 16); ctr1[0]=1;
    ChaCha20_ctr32(ct, pt, ptlen, k, ctr1);

    size_t ctxsz=Poly1305_ctx_size();
    void *ctx=malloc(ctxsz+64);
    Poly1305_Init(ctx, otk);
    Poly1305_Update(ctx, aad, aadlen);
    if(aadlen & 15){ unsigned char z[16]={0}; Poly1305_Update(ctx, z, 16-(aadlen&15)); }
    Poly1305_Update(ctx, ct, ptlen);
    if(ptlen & 15){ unsigned char z[16]={0}; Poly1305_Update(ctx, z, 16-(ptlen&15)); }
    unsigned char lens[16];
    uint64_t al=aadlen, pl=ptlen;
    memcpy(lens, &al, 8); memcpy(lens+8, &pl, 8);
    Poly1305_Update(ctx, lens, 16);
    Poly1305_Final(ctx, tag);
    free(ctx);
}

