#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>

extern void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp,
                           size_t len, const unsigned int key[8],
                           const unsigned int counter[4]);
typedef struct poly1305_context POLY1305;
extern size_t Poly1305_ctx_size(void);
extern void Poly1305_Init(POLY1305*, const unsigned char key[32]);
extern void Poly1305_Update(POLY1305*, const unsigned char*, size_t);
extern void Poly1305_Final(POLY1305*, unsigned char mac[16]);

#define NC 6
#define NP 3

typedef struct { unsigned char *out; const unsigned char *in; size_t len; unsigned int key[8]; unsigned int ctr[4]; } cjob;
typedef struct { const unsigned char *in; size_t len; unsigned char key[32]; unsigned char mac[16]; void *ctx; } pjob;

static void *cw(void *a){ cjob *j=a; ChaCha20_ctr32(j->out, j->in, j->len, j->key, j->ctr); return NULL; }
static void *pw(void *a){ pjob *j=a; Poly1305_Init(j->ctx, j->key); Poly1305_Update(j->ctx, j->in, j->len); Poly1305_Final(j->ctx, j->mac); return NULL; }

static void store64(unsigned char *p, uint64_t v){ memcpy(p, &v, 8); }

/* Encrypt in place semantics: pt -> ct (separate buffers). tag 16 bytes. */
void chacha20poly1305_encrypt(unsigned char *ct, unsigned char tag[16],
                              const unsigned char key[32], const unsigned char nonce[12],
                              const unsigned char *pt, size_t ptlen,
                              const unsigned char *aad, size_t aadlen){
    unsigned int k[8];
    memcpy(k, key, 32);
    unsigned int base[4];
    base[0]=0; memcpy(&base[1], nonce, 12);

    /* block 0 -> one-time poly key */
    unsigned char block0[64];
    unsigned char zeros[64]={0};
    unsigned int ctr0[4]; memcpy(ctr0, base, 16); ctr0[0]=0;
    ChaCha20_ctr32(block0, zeros, 64, k, ctr0);
    unsigned char otk[32]; memcpy(otk, block0, 32);

    /* parallel chacha over plaintext, counter starts at 1 */
    int nc = NC;
    if(ptlen < (size_t)nc*4096) nc = 1;
    cjob cjobs[NC];
    pthread_t th[NC+NP];
    size_t off=0;
    size_t chunk = (ptlen/nc) & ~((size_t)63);
    if(chunk==0){ nc=1; chunk=ptlen; }
    for(int i=0;i<nc;i++){
        size_t L = (i==nc-1)? (ptlen-off) : chunk;
        unsigned long long c = 1ull + off/64;
        cjobs[i].out = ct+off; cjobs[i].in = pt+off; cjobs[i].len = L;
        memcpy(cjobs[i].key, k, 32);
        cjobs[i].ctr[0] = (unsigned)(c & 0xffffffffu);
        cjobs[i].ctr[1] = base[1];
        cjobs[i].ctr[2] = base[2];
        cjobs[i].ctr[3] = base[3] + (unsigned)(c>>32);
        off += L;
        if(nc>1) pthread_create(&th[i], NULL, cw, &cjobs[i]);
    }
    if(nc==1) ChaCha20_ctr32(ct, pt, ptlen, cjobs[0].key, cjobs[0].ctr);
    else for(int i=0;i<nc;i++) pthread_join(th[i], NULL);

    /* poly1305 over aad || pad || ct || pad || lens, split across NP threads.
       We compute each chunk's poly independently then... can't combine. So do it
       single-threaded for correctness. Throughput of poly is high enough that the
       chacha stage dominates; but we still parallelize the big ct region by
       computing it concurrently with nothing. Single thread poly: */
    size_t ctxsz = Poly1305_ctx_size();
    void *ctx = malloc(ctxsz+64);
    Poly1305_Init(ctx, otk);
    if(aad && aadlen){
        Poly1305_Update(ctx, aad, aadlen);
        if(aadlen & 15){ unsigned char z[16]={0}; Poly1305_Update(ctx, z, 16-(aadlen&15)); }
    }
    Poly1305_Update(ctx, ct, ptlen);
    if(ptlen & 15){ unsigned char z[16]={0}; Poly1305_Update(ctx, z, 16-(ptlen&15)); }
    unsigned char lens[16];
    store64(lens, aadlen); store64(lens+8, ptlen);
    Poly1305_Update(ctx, lens, 16);
    Poly1305_Final(ctx, tag);
    free(ctx);
}
EOF
