extern void chacha20_xor8(unsigned char *out, const unsigned char *in, size_t len, const unsigned int key[8], const unsigned int counter[4]);
extern void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len, const unsigned int key[8], const unsigned int counter[4]);
static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}
typedef struct { unsigned char *out,*in; size_t len; unsigned int key[8]; unsigned int ctr[4]; int which; } job;
static void *w(void *a){ job*j=a;
    if(j->which==0) chacha20_xor8(j->out,j->in,j->len,j->key,j->ctr);
    else ChaCha20_ctr32(j->out,j->in,j->len,j->key,j->ctr);
    return NULL; }
int main(){
    size_t total=40960000; total &= ~511ull;
    int nts[]={1,2,3,4,6};
    for(int ti=0; ti<5; ti++){
        int nt=nts[ti];
        size_t chunk=(total/nt)&~511ull;
        unsigned char *in=malloc(total),*out=malloc(total); memset(in,1,total);
        unsigned int key[8]; for(int i=0;i<8;i++) key[i]=0x1000*i+3;
        job jobs[8]; pthread_t th[8];
        int iters=6;
        double t0=now();
        for(int it=0; it<iters; it++){
            size_t off=0;
            for(int i=0;i<nt;i++){
                size_t L=(i==nt-1)?(total-off):chunk;
                jobs[i].out=out+off; jobs[i].in=in+off; jobs[i].len=L; jobs[i].which=0;
                memcpy(jobs[i].key,key,32);
                unsigned long long c=1ull+off/64;
                jobs[i].ctr[0]=(unsigned)c; jobs[i].ctr[1]=0x11111111; jobs[i].ctr[2]=0x22222222; jobs[i].ctr[3]=(unsigned)(c>>32);
                off+=L; pthread_create(&th[i],NULL,w,&jobs[i]);
            }
            for(int i=0;i<nt;i++) pthread_join(th[i],NULL);
        }
        double t1=now();
        printf("our kernel nt=%d: %.2f ms  %.0f MB/s\n", nt,(t1-t0)/iters*1000,(total/1e6)/((t1-t0)/iters));
        free(in); free(out);
    }
    return 0;
}
