extern void Poly1305_Update(POLY1305*, const unsigned char*, size_t);
extern void Poly1305_Final(POLY1305*, unsigned char mac[16]);

typedef struct { uint64_t h0,h1,h2; uint64_t r0,r1; uint64_t s1; } st;

static void blocks(st *s, const unsigned char *m, size_t bytes){
    uint64_t h0=s->h0,h1=s->h1,h2=s->h2,r0=s->r0,r1=s->r1,s1=s->s1;
    while(bytes>=16){
        uint64_t t0,t1;
        memcpy(&t0,m,8); memcpy(&t1,m+8,8);
        h0+=t0; 
        uint64_t c=(h0<t0);
        h1+=t1+c; c=(h1<t1)||(c&&h1==t1);
        h2+=c+1; /* hibit */
        /* h *= r mod 2^130-5 */
        __uint128_t d0=(__uint128_t)h0*r0 + (__uint128_t)h1*s1 + (__uint128_t)h2*r1*5?0:0;
        /* redo properly */
        __uint128_t x0 = (__uint128_t)h0*r0;
        __uint128_t x1 = (__uint128_t)h0*r1 + (__uint128_t)h1*r0 + (__uint128_t)h2*s1;
        __uint128_t x2 = (__uint128_t)h1*r1 + (__uint128_t)h2*r0;
        /* s1 = r1*5? standard: s1 = r1 + (r1>>2) = r1*5 >> 2? Let's use the classic formulation:
           h = h0 + h1*2^64 + h2*2^128, r = r0 + r1*2^64
           h*r = h0*r0 + (h0*r1+h1*r0)*2^64 + (h1*r1+h2*r0)*2^128 + h2*r1*2^192
           reduce 2^130 == 5: 2^128 = 4*2^130/4... standard reduction:
           Let me just use 130-bit reduction: value mod (2^130-5). */
        (void)x0;(void)x1;(void)x2;(void)d0;
        m+=16; bytes-=16;
    }
    s->h0=h0;s->h1=h1;s->h2=h2;
}

