#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
typedef struct poly1305_context POLY1305;
extern size_t Poly1305_ctx_size(void);
extern void Poly1305_Init(POLY1305*, const unsigned char key[32]);
extern void Poly1305_Update(POLY1305*, const unsigned char*, size_t);
extern void Poly1305_Final(POLY1305*, unsigned char mac[16]);

typedef struct { uint64_t h0,h1,h2,r0,r1,s1; } st;

static void init(st *s, const unsigned char key[32]){
    uint64_t t0,t1; memcpy(&t0,key,8); memcpy(&t1,key+8,8);
    s->r0 = t0 & 0x0ffffffc0fffffffULL;
    s->r1 = t1 & 0x0ffffffc0ffffffcULL;
    s->s1 = s->r1 + (s->r1 >> 2);
    s->h0=s->h1=s->h2=0;
}
static void blocks(st *s, const unsigned char *m, size_t n, int hibit){
    uint64_t h0=s->h0,h1=s->h1,h2=s->h2,r0=s->r0,r1=s->r1,s1=s->s1;
    uint64_t hib = hibit ? (1ULL<<32) : 0; /* added into h2's low? see below */
    while(n>=16){
        uint64_t t0,t1; memcpy(&t0,m,8); memcpy(&t1,m+8,8);
        __uint128_t acc0 = h0 + t0;
        __uint128_t acc1 = h1 + t1 + (acc0 >> 64);
        acc0 &= (uint64_t)-1;
        uint64_t c = (uint64_t)(acc1 >> 64);
        acc1 &= (uint64_t)-1;
        /* add hibit (1<<128) */
        __uint128_t hh2 = h2 + c + (hibit?1:0);
        h0=(uint64_t)acc0; h1=(uint64_t)acc1; h2=(uint64_t)hh2;
        /* multiply by r */
        __uint128_t x0 = (__uint128_t)h0*r0;
        __uint128_t x1 = (__uint128_t)h0*r1 + (__uint128_t)h1*r0;
        __uint128_t x2 = (__uint128_t)h1*r1 + (__uint128_t)h2*r0;
        __uint128_t x3 = (__uint128_t)h2*r1;
        /* h2 fits in < ~4, so x3 small. Reduce: 2^128 ≡ 4? No: 2^130 ≡ 5.
           Represent value = x0 + x1*2^64 + x2*2^128 + x3*2^192.
           2^130 = 5 => 2^128 = 2^130/4 not integer. Use: 2^130 ≡ 5, so
           a*2^130 = 5a. Value = lo130 + hi130*2^130 ≡ lo130 + 5*hi130.
           lo130 = bottom 130 bits. */
        __uint128_t v0 = x0;                          /* bits 0..127+ */
        __uint128_t v1 = x1 + (v0 >> 64); v0 &= (uint64_t)-1;   /* v0: 64, v1 carries bits 64.. */
        __uint128_t v2 = x2 + (v1 >> 64); v1 &= (uint64_t)-1;
        __uint128_t v3 = x3 + (v2 >> 64); v2 &= (uint64_t)-1;
        /* now value = v0 + v1<<64 + v2<<128 + v3<<192, each vi < 2^64 except v3 maybe bigger but small */
        /* bottom 130 bits = v0 + (v1<<64) + (v2 & 3)<<128 */
        uint64_t lo0 = (uint64_t)v0;
        uint64_t lo1 = (uint64_t)v1;
        uint64_t lo2 = (uint64_t)v2 & 3ULL;
        /* hi130 = (v2>>2) + v3<<62 */
        __uint128_t hi = (v2 >> 2) + (v3 << 62);
        /* add 5*hi */
        __uint128_t s0 = lo0 + 5*hi;
        __uint128_t s1c = lo1 + (s0 >> 64); s0 &= (uint64_t)-1;
        __uint128_t s2c = lo2 + (s1c >> 64); s1c &= (uint64_t)-1;
        /* s2c may exceed 4 (130 bits) -> fold again */
        if(s2c >= 4){
            __uint128_t extra = s2c >> 2; s2c &= 3;
            s0 += 5*extra; s1c += s0>>64; s0 &= (uint64_t)-1; s2c += s1c>>64; s1c &= (uint64_t)-1;
        }
        h0=(uint64_t)s0; h1=(uint64_t)s1c; h2=(uint64_t)s2c;
        m+=16; n-=16;
    }
    s->h0=h0;s->h1=h1;s->h2=h2;
}
static void finish(st *s, unsigned char mac[16], const unsigned char s_key[16]){
    uint64_t h0=s->h0,h1=s->h1,h2=s->h2;
    uint64_t g0=h0+5, g1=h1+(g0<h0?1:0), g2=h2+(g1< (h1+(g0<h0?1:0))?0:0);
    /* simpler carry */
    __uint128_t gg0=h0+5; __uint128_t gg1=h1+(gg0>>64); gg0&=(uint64_t)-1; __uint128_t gg2=h2+(gg1>>64); gg1&=(uint64_t)-1;
    uint64_t mask = -((uint64_t)(gg2 >> 2)); /* if h>=p, top bit of the +5 carry */
    h0 = (h0 & ~mask) | ((uint64_t)gg0 & mask);
    h1 = (h1 & ~mask) | ((uint64_t)gg1 & mask);
    uint64_t k0,k1; memcpy(&k0,s_key,8); memcpy(&k1,s_key+8,8);
    __uint128_t f0=h0+k0; __uint128_t f1=h1+k1+(f0>>64);
    uint64_t o0=(uint64_t)f0,o1=(uint64_t)f1;
    memcpy(mac,&o0,8); memcpy(mac+8,&o1,8);
}
static void poly(const unsigned char *m, size_t n, const unsigned char key[32], unsigned char mac[16]){
    st s; init(&s,key);
    size_t full=n&~15ull;
    blocks(&s,m,full,1);
    if(n&15){
        unsigned char pad[16]={0}; memcpy(pad,m+full,n&15); pad[n&15]=1;
        blocks(&s,pad,16,0);
    }
    finish(&s,mac,key+16);
}
int main(){
    size_t sz=Poly1305_ctx_size();
    void *ctx=malloc(sz+64);
    unsigned char key[32]; for(int i=0;i<32;i++) key[i]=i*7+3;
    for(size_t n : (size_t[]){0,1,15,16,17,31,32,64,1000,4096,1000000}){
        unsigned char *m=malloc(n+1); for(size_t i=0;i<n;i++) m[i]=i*13+5;
        unsigned char a[16], b[16];
        Poly1305_Init(ctx,key); Poly1305_Update(ctx,m,n); Poly1305_Final(ctx,a);
        poly(m,n,key,b);
        int ok=!memcmp(a,b,16);
        printf("n=%zu %s\n", n, ok?"OK":"FAIL");
        if(!ok){ printf(" ref "); for(int i=0;i<16;i++) printf("%02x",a[i]); printf("\n got "); for(int i=0;i<16;i++) printf("%02x",b[i]); printf("\n"); return 1; }
        free(m);
    }
    /* speed */
    size_t n=40960000; unsigned char *m=malloc(n); memset(m,1,n);
    unsigned char mac[16];
    int iters=4; struct timespec ts; 
    double t0,t1;
    clock_gettime(CLOCK_MONOTONIC,&ts); t0=ts.tv_sec+ts.tv_nsec*1e-9;
    for(int i=0;i<iters;i++) poly(m,n,key,mac);
    clock_gettime(CLOCK_MONOTONIC,&ts); t1=ts.tv_sec+ts.tv_nsec*1e-9;
    printf("our poly: %.2f ms\n",(t1-t0)/iters*1000);
    clock_gettime(CLOCK_MONOTONIC,&ts); t0=ts.tv_sec+ts.tv_nsec*1e-9;
    for(int i=0;i<iters;i++){ Poly1305_Init(ctx,key); Poly1305_Update(ctx,m,n); Poly1305_Final(ctx,mac); }
    clock_gettime(CLOCK_MONOTONIC,&ts); t1=ts.tv_sec+ts.tv_nsec*1e-9;
    printf("openssl poly: %.2f ms\n",(t1-t0)/iters*1000);
    return 0;
}
EOF
